<?php
declare(strict_types=1);
require_once dirname(__DIR__, 2) . '/config/database.php';
require_once dirname(__DIR__, 2) . '/includes/auth.php';
requireRole(4);
$stats = $pdo->query("SELECT COUNT(*) AS total, SUM(status_arsip = 'Inaktif') AS aktif, SUM(tanggal_jatuh_tempo IS NOT NULL AND tanggal_jatuh_tempo >= CURRENT_DATE) AS retensi, SUM(tanggal_jatuh_tempo BETWEEN CURRENT_DATE AND DATE_ADD(CURDATE(), INTERVAL 1 YEAR)) AS musnah_satu_tahun, SUM(status_arsip = 'Musnah' AND YEAR(updated_at) = YEAR(CURDATE())) AS musnah_tahun_ini FROM arsip")->fetch();
$units = $pdo->query('SELECT u.nama_unit, COUNT(a.arsip_id) AS jumlah FROM unit_kerja u LEFT JOIN arsip a ON a.unit_id = u.unit_id GROUP BY u.unit_id, u.nama_unit ORDER BY jumlah DESC, u.nama_unit')->fetchAll();
$types = $pdo->query('SELECT j.nama_jenis, COUNT(a.arsip_id) AS jumlah FROM jenis_surat j LEFT JOIN arsip a ON a.jenis_surat_id = j.jenis_surat_id GROUP BY j.jenis_surat_id, j.nama_jenis ORDER BY jumlah DESC, j.nama_jenis')->fetchAll();
$trend = $pdo->query("SELECT DATE_FORMAT(created_at, '%b %Y') AS bulan, COUNT(*) AS jumlah FROM arsip WHERE created_at >= DATE_SUB(CURDATE(), INTERVAL 5 MONTH) GROUP BY DATE_FORMAT(created_at, '%Y-%m'), DATE_FORMAT(created_at, '%b %Y') ORDER BY MIN(created_at)")->fetchAll();
$retention = $pdo->query("SELECT SUM(status_arsip = 'Inaktif') AS aktif, SUM(tanggal_jatuh_tempo IS NOT NULL AND tanggal_jatuh_tempo >= CURRENT_DATE) AS retensi, SUM(status_arsip = 'Permanen') AS permanen, SUM(status_arsip = 'Musnah') AS musnah FROM arsip")->fetch();
$schedule = $pdo->query("SELECT SUM(v.tanggal_jatuh_tempo BETWEEN CURRENT_DATE AND DATE_ADD(CURDATE(), INTERVAL 7 DAY)) AS h7, SUM(YEAR(v.tanggal_jatuh_tempo) = YEAR(CURDATE()) AND MONTH(v.tanggal_jatuh_tempo) = MONTH(CURDATE())) AS bulan_ini, SUM(YEAR(v.tanggal_jatuh_tempo) = YEAR(CURDATE())) AS tahun_ini FROM view_jadwal_pemusnahan v")->fetch();
$name = (string) ($_SESSION['nama_lengkap'] ?? $_SESSION['username'] ?? 'User');
$chartData = ['units' => ['labels' => array_column($units, 'nama_unit'), 'data' => array_map('intval', array_column($units, 'jumlah'))], 'types' => ['labels' => array_column($types, 'nama_jenis'), 'data' => array_map('intval', array_column($types, 'jumlah'))], 'trend' => ['labels' => array_column($trend, 'bulan'), 'data' => array_map('intval', array_column($trend, 'jumlah'))], 'retention' => ['labels' => ['Inaktif', 'Dalam Retensi', 'Permanen', 'Musnah'], 'data' => array_map('intval', [$retention['aktif'], $retention['retensi'], $retention['permanen'], $retention['musnah']])]];
?>
