aintainAspectRatio:false,plugins:{legend:{display:false}}};new Chart(document.getElementById('unitChart'),{type:'bar',data:{labels:d.units.labels,datasets:[{data:d.units.data,backgroundColor:colors,borderRadius:7,borderSkipped:false}]},options:{...base,scales:{x:{grid:{display:false},ticks:{font:{size:10},maxRotation:0,minRotation:0}},y:{beginAtZero:true,ticks:{precision:0}}}}});new Chart(document.getElementById('typeChart'),{type:'doughnut',data:{labels:d.types.labels,datasets:[{data:d.types.data,backgroundColor:colors,borderWidth:0}]},options:{...base,cutout:'62%',plugins:{legend:{display:true,position:'right',labels:{boxWidth:10,font:{size:10}}}}}});new Chart(document.getElementById('trendChart'),{type:'line',data:{labels:d.trend.labels,datasets:[{data:d.trend.data,borderColor:'#2563eb',backgroundColor:'#2563eb22',fill:true,tension:.35,pointRadius:4,pointBackgroundColor:'#2563eb'}]},options:{...base,scales:{x:{grid:{display:false},ticks:{font:{size:10}}},y:{beginAtZero:true,ticks:{precision:0}}}}});new Chart(document.getElementById('retentionChart'),{type:'doughnut',data:{labels:d.retention.labels,datasets:[{data:d.retention.data,backgroundColor:colors.slice(0,4),borderWidth:0}]},options:{...base,cutout:'62%'}});</script><script>const content=document.getElementById('pimpinan-content'),dashboard=content.innerHTML;function setActive(page){document.querySelectorAll('[data-page]').forEach(a=>a.classList.toggle('nav-active',a.dataset.page===page));document.querySelectorAll('[data-page="arsip"]').forEach(a=>a.classList.toggle('nav-active',page==='arsip'))}const supportedQueryKeys=new Set(['q','unit_id','jenis_surat_id','klasifikasi_id','status','from','to','group']);function supportedQuery(query=''){const source=query instanceof URLSearchParams?query:new URLSearchParams(String(query).replace(/^[?&]/,''));const params=new URLSearchParams();source.forEach((value,key)=>{if(supportedQueryKeys.has(key))params.set(key,value)});return params}async function loadPage(page,push=true,query=''){const params=supportedQuery(query);setActive(page);if(page==='dashboard'){content.innerHTML=dashboard;if(push)history.pushState({page},'',location.pathname);bindFragment();return}content.innerHTML='<p class="spa-loading">Memuat data...</p>';try{const request=new URLSearchParams(params);request.set('page',page);const r=await fetch('fragment.php?'+request,{credentials:'same-origin'});if(!r.ok)throw new Error('HTTP '+r.status);content.innerHTML=await r.text();if(push){const url=new URL(location.href);url.search='';url.searchParams.set('page',page);params.forEach((value,key)=>url.searchParams.set(key,value));history.pushState({page},'',url.pathname+url.search)}bindFragment()}catch(e){content.innerHTML='<p class="spa-loading">Gagal memuat data. Silakan coba lagi.</p>'}}function bindFragment(){const form=content.querySelector('.spa-search');if(form)form.addEventListener('submit',e=>{e.preventDefault();const params=new URLSearchParams({q:form.q.value,unit_id:form.unit_id.value,jenis_surat_id:form.jenis_surat_id.value,klasifikasi_id:form.klasifikasi_id.value,status:form.status.value,from:form.from.value,to:form.to.value});loadPage('arsip',false,params)});content.querySelectorAll('.spa-detail').forEach(b=>b.addEventListener('click',()=>openPimpinanDetail(b.dataset.id)));content.querySelector('.spa-back')?.addEventListener('click',()=>history.back());content.querySelectorAll('.spa-preview').forEach(b=>b.addEventListener('click',()=>{const panel=content.querySelector('.spa-preview-panel');if(!panel)return;panel.hidden=false;panel.querySelector('iframe').src='../../api/preview-arsip.php?id='+encodeURIComponent(b.dataset.file);panel.querySelector('.spa-preview-close')?.addEventListener('click',()=>{panel.hidden=true;panel.querySelector('iframe').src='about:blank'},{once:true})}))}document.querySelectorAll('[data-page]').forEach(a=>a.addEventListener('click',e=>{if(e.button||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();const url=new URL(a.href,location.href);const page=a.dataset.page||url.searchParams.get('page');if(!page)return;loadPage(page,true,url.searchParams)}));window.addEventListener('popstate',()=>{const params=new URLSearchParams(location.search);const page=params.get('page')||'dashboard';loadPage(page,false,params)});bindFragment();const initPage=new URLSearchParams(location.search).get('page')||'dashboard';if(initPage!=='dashboard')loadPage(initPage,false,location.search.includes('?')?location.search.slice(location.search.indexOf('?')+1).replace(/^page=[^&]*&?/,'&'):'' );</script><style>.spa-loading{padding:40px;text-align:center;color:#64748b}.spa-detail,.spa-back,.spa-preview,.spa-close{border:0;border-radius:7px;padding:7px 10px;color:#fff;background:#2563eb;cursor:pointer}.spa-modal{position:fixed;inset:0;z-index:50;display:grid;place-items:center;padding:24px;background:#0f172a99}.spa-modal[hidden]{display:none!important;pointer-events:none!important}.spa-modal>div{width:min(1000px,100%);height:min(80vh,700px);padding:12px;border-radius:14px;background:#fff}.spa-modal iframe{width:100%;height:calc(100% - 42px);margin-top:8px;border:0}.spa-search{flex-wrap:wrap}.spa-search input,.spa-search select{min-width:150px}</style><script>function initializeDashboardCharts(){if(typeof Chart==='undefined'||typeof d==='undefined')return;const make=(id,config)=>{const canvas=document.getElementById(id);if(!canvas)return;const old=Chart.getChart(canvas);if(old)old.destroy();new Chart(canvas,config)};const colors=['#2563eb','#16a34a','#f97316','#7c3aed','#14b8a6','#94a3b8'],base={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}}};make('unitChart',{type:'bar',data:{labels:d.units.labels,datasets:[{data:d.units.data,backgroundColor:colors,borderRadius:7,borderSkipped:false}]},options:{...base,scales:{x:{grid:{display:false},ticks:{font:{size:10},maxRotation:0,minRotation:0}},y:{beginAtZero:true,ticks:{precision:0}}}}});make('typeChart',{type:'doughnut',data:{labels:d.types.labels,datasets:[{data:d.types.data,backgroundColor:colors,borderWidth:0}]},options:{...base,cutout:'62%',plugins:{legend:{display:true,position:'right',labels:{boxWidth:10,font:{size:10}}}}}});make('trendChart',{type:'line',data:{labels:d.trend.labels,datasets:[{data:d.trend.data,borderColor:'#2563eb',backgroundColor:'#2563eb22',fill:true,tension:.35,pointRadius:4,pointBackgroundColor:'#2563eb'}]},options:{...base,scales:{x:{grid:{display:false},ticks:{font:{size:10}}},y:{beginAtZero:true,ticks:{precision:0}}}}});make('retentionChart',{type:'doughnut',data:{labels:d.retention.labels,datasets:[{data:d.retention.data,backgroundColor:colors.slice(0,4),borderWidth:0}]},options:{...base,cutout:'62%'}})};const spaLoadPage=loadPage;loadPage=async function(page,push=true,query=''){await spaLoadPage(page,push,query);if(page==='dashboard')initializeDashboardCharts()};initializeDashboardCharts();</script><div class="spa-modal" id="pimpinan-detail-modal" hidden><div class="detail-modal-dialog"><header><div><i class="material-symbols-outlined">folder_open</i><span><b>DETAIL ARSIP</b><small>Informasi lengkap dokumen arsip</small></span></div><button class="spa-close" type="button" aria-label="Tutup detail">close</button></header><div class="detail-modal-body"></div><footer><button class="spa-close" type="button">Tutup</button></footer></div></div><script>const detailModal=document.getElementById('pimpinan-detail-modal'),detailBody=detailModal.querySelector('.detail-modal-body');async function openPimpinanDetail(id,push=true){detailBody.innerHTML='<p class="spa-loading">Memuat detail arsip...</p>';detailModal.hidden=false;try{const r=await fetch('fragment.php?page=detail&id='+encodeURIComponent(id),{credentials:'same-origin'});if(!r.ok)throw new Error('HTTP '+r.status);const html=await r.text();if(!html.trim())throw new Error('Respons kosong');detailBody.innerHTML=html;if(push)history.pushState({page:'detail',id},'',location.pathname+'?page=detail&id='+encodeURIComponent(id));const previewModal=detailBody.querySelector('.spa-preview-panel'),previewFrame=previewModal?.querySelector('iframe'),previewName=previewModal?.querySelector('.spa-preview-name'),previewFallback=previewModal?.querySelector('.spa-preview-fallback');const closePreview=()=>{if(!previewModal)return;previewModal.hidden=true;if(previewFrame)previewFrame.removeAttribute('src');if(previewFallback)previewFallback.hidden=true};const openPreview=(fileId,fileName)=>{if(!previewModal||!previewFrame)return;previewName.textContent=fileName||'';previewFallback.querySelector('.spa-download').href='../../api/download-arsip.php?id='+encodeURIComponent(fileId);previewFallback.hidden=true;previewFrame.style.display='block';previewFrame.onload=()=>{previewFrame.style.display='block'};previewFrame.onerror=()=>{previewFrame.style.display='none';previewFallback.hidden=false;previewFrame.removeAttribute('src')};const url='../../api/preview-arsip.php?id='+encodeURIComponent(fileId);fetch(url,{method:'HEAD',credentials:'same-origin'}).then(response=>{if(!response.ok)throw new Error('Preview gagal');previewFrame.src=url}).catch(()=>{previewFrame.style.display='none';previewFallback.hidden=false});previewModal.hidden=false};detailBody.addEventListener('click',event=>{const previewButton=event.target.closest('.spa-preview');if(previewButton){event.preventDefault();openPreview(previewButton.dataset.file,previewButton.dataset.name);return}if(event.target.closest('.spa-preview-close')){event.preventDefault();closePreview();return}if(event.target.closest('.spa-preview-panel')&&event.target.classList.contains('spa-preview-panel')){closePreview()}},true);detailBody.querySelector('.spa-back')?.addEventListener('click',()=>{detailModal.hidden=true;history.back()});detailBody.querySelector('.spa-close')?.addEventListener('click',()=>{detailModal.hidden=true;history.back()})}catch(e){detailBody.innerHTML='<section class="panel"><h2>Detail Arsip</h2><p class="empty-state">Arsip tidak ditemukan atau tidak dapat diakses.</p></section>'}}document.addEventListener('click',e=>{const button=e.target.closest('.spa-detail');if(!button)return;e.preventDefault();e.stopImmediatePropagation();openPimpinanDetail(button.dataset.id)} ,true);function closePimpinanDetail(){if(detailModal.hidden)return;detailModal.hidden=true;detailBody.innerHTML='';if(new URLSearchParams(location.search).get('page')==='detail')history.back()}document.addEventListener('click',e=>{if(!e.target.closest('#pimpinan-detail-modal .spa-close'))return;e.preventDefault();e.stopImmediatePropagation();closePimpinanDetail()},true);document.addEventListener('keydown',e=>{if(e.key==='Escape')closePimpinanDetail()});function resetPimpinanDetail(){detailModal.hidden=true;detailBody.innerHTML='';document.body.style.overflow=''}resetPimpinanDetail();window.addEventListener('pageshow',e=>{if(e.persisted||new URLSearchParams(location.search).get('page')!=='detail')resetPimpinanDetail()});window.addEventListener('popstate',()=>{const q=new URLSearchParams(location.search);if(q.get('page')!=='detail'){detailModal.hidden=true;detailBody.innerHTML=''}});const directDetail=new URLSearchParams(location.search);if(directDetail.get('page')==='detail'){setTimeout(()=>openPimpinanDetail(directDetail.get('id')||'',false),0)}</script><style>#pimpinan-detail-modal>.detail-modal-body{height:calc(100% - 42px);overflow:auto;margin-top:8px}#pimpinan-detail-modal>.detail-modal-body .panel{box-shadow:none}.spa-preview-panel{position:fixed!important;inset:0!important;z-index:101!important;display:grid;place-items:center;padding:20px;background:#0f172a88;backdrop-filter:blur(3px)}.spa-preview-panel[hidden]{display:none!important}.spa-preview-shell{display:grid;grid-template-rows:auto minmax(0,1fr);width:min(1200px,calc(100vw - 40px));height:min(90vh,900px);overflow:hidden;border-radius:18px;background:#fff;box-shadow:0 28px 80px #0f172a66}.spa-preview-shell header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid #e5eaf2}.spa-preview-shell header b,.spa-preview-shell header small{display:block}.spa-preview-shell header small{margin-top:3px;color:#64748b;font-size:11px}.spa-preview-close{border:0;border-radius:9px;padding:8px 13px;background:#edf2f9;color:#172554;font:inherit;cursor:pointer}.spa-preview-body{min-height:0;padding:16px;background:#f8fafc}.spa-preview-body iframe{width:100%;height:100%;border:0;border-radius:10px;background:#fff}.spa-preview-fallback{display:grid;place-items:center;gap:14px;height:100%;text-align:center}.spa-preview-fallback .spa-download{padding:8px 13px;border-radius:9px;background:#2563eb;color:#fff;text-decoration:none}</style></body></html>
